import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]
    limit = max(values)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, limit + 1, p):
                if spf[v] == v:
                    spf[v] = p

    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if spf[p] == p:
            for v in range(p, limit + 1, p):
                phi[v] -= phi[v] // p

    weighted_divisor_sums = [0] * (limit + 1)
    answer = 0
    weight = 1
    output = []

    for x in values:
        y = x
        factors = []
        while y > 1:
            p = spf[y]
            exponent = 0
            while y % p == 0:
                y //= p
                exponent += 1
            factors.append((p, exponent))

        divisors = [1]
        for p, exponent in factors:
            old = divisors[:]
            power = 1
            for _ in range(exponent):
                power *= p
                divisors.extend(d * power for d in old)

        contribution = 0
        for d in divisors:
            contribution += phi[d] * weighted_divisor_sums[d]
        answer = (2 * answer + contribution) % MOD
        output.append(str(answer))

        for d in divisors:
            new_value = weighted_divisor_sums[d] + weight
            if new_value >= MOD:
                new_value -= MOD
            weighted_divisor_sums[d] = new_value
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

