class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        top = second = 0
        unique_pair = -1
        gains = [0] * m
        total = 0

        for right in range(1, n + 1):
            for left, idx in buckets[right]:
                if left > top:
                    second = top
                    top = left
                    unique_pair = idx
                elif left == top:
                    second = top
                    unique_pair = -1
                elif left > second:
                    second = left

            total += right - top
            if unique_pair != -1:
                gains[unique_pair] += top - second

        return total + max(gains)

