class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Binomial coefficients for choosing ones in a suffix.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]
        allowed = [c for c in range(1, n + 1) if c == 1 or 1 + depth[c] <= k]
        ans = 0
        prefix = 0
        for i, bit in enumerate(s):
            rem = n - i - 1
            if bit == '1':
                # Put zero here; choose remaining ones among the suffix.
                for c in allowed:
                    need = c - prefix
                    if 0 <= need <= rem:
                        ans += comb[rem][need]
                prefix += 1
        return ans % MOD

