def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]
    u = data[2::2]
    d = data[3::2]

    def feasible(h):
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            lo = max(max(0, h - d[i]), lo - x)
            hi = min(min(u[i], h), hi + x)
            if lo > hi:
                return False
        return True

    left = 0
    right = min(u[i] + d[i] for i in range(n))
    while left < right:
        mid = (left + right + 1) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid - 1

    total = sum(u[i] + d[i] for i in range(n))
    print(total - n * left)

if __name__ == '__main__':
    main()

