from typing import List
from functools import lru_cache

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        @lru_cache(None)
        def go(r, c, d, expected, can_turn):
            if not (0 <= r < n and 0 <= c < m) or grid[r][c] != expected:
                return 0
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            nxt = 0 if expected == 2 else 2
            best = go(nr, nc, d, nxt, can_turn)
            if can_turn:
                td = (d + 1) % 4
                tr, tc = r + dirs[td][0], c + dirs[td][1]
                best = max(best, go(tr, tc, td, nxt, False))
            return 1 + best

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        ans = max(ans, 1 + go(r + dr, c + dc, d, 2, True))
        return ans

