from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Factorials are capped at the original rank: anything larger is
        # indistinguishable for deciding whether it contains the current k-th item.
        cap = k
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        def completions(odd: int, even: int, previous_parity: int) -> int:
            length = odd + even
            if length == 0:
                return 1
            first_parity = 1 - previous_parity
            need_odd = (length + 1) // 2 if first_parity == 1 else length // 2
            need_even = length - need_odd
            if odd != need_odd or even != need_even:
                return 0
            return min(cap, fact[odd] * fact[even])

        unused = set(range(1, n + 1))
        answer = []
        previous_parity = None

        for _ in range(n):
            chosen = None
            for value in sorted(unused):
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                remaining_odd = sum(v % 2 == 1 for v in unused) - (parity == 1)
