class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append((powers[i] + (powers[j] if j != i else 0)) % k)

        full = (1 << k) - 1
        # dp[i] is a bitset of residues attainable by positions i..m-1.
        dp = [0] * (m + 1)
        dp[m] = 1  # the empty suffix contributes residue zero
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            mask = 0
            following = dp[i + 1]
            for d in range(10):
                shift = d * c % k
                if shift == 0:
                    mask |= following
                else:
                    mask |= ((following << shift) | (following >> (k - shift))) & full
            dp[i] = mask

        chars = ['0'] * n
        residue = 0
        for i, c in enumerate(coeff):
            lowest_digit = 1 if i == 0 else 0
            for d in range(9, lowest_digit - 1, -1):
                needed = (-residue - d * c) % k
                if (dp[i + 1] >> needed) & 1:
                    chars[i] = chars[n - 1 - i] = str(d)
                    residue = (residue + d * c) % k
                    break
        return ''.join(chars)

