from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        levels = n.bit_length()
        dest = [[n] * n for _ in range(levels)]
        sums = [[0] * n for _ in range(levels)]

        # A transition from a record maximum p to its next greater element q
        # covers p+1 ... q-1, all of which need to be raised to nums[p].
        for p in range(n):
            q = nxt[p]
            dest[0][p] = q
            sums[0][p] = nums[p] * (q - p - 1) - (prefix[q] - prefix[p + 1])

        for level in range(1, levels):
            prev_dest = dest[level - 1]
            prev_sum = sums[level - 1]
            cur_dest = dest[level]
            cur_sum = sums[level]
            for p in range(n):
                mid = prev_dest[p]
                if mid < n:
                    cur_dest[p] = prev_dest[mid]
                    cur_sum[p] = prev_sum[p] + prev_sum[mid]
                else:
                    cur_sum[p] = prev_sum[p]

        def cost(left: int, right: int) -> int:
            p = left
            total = 0
            limit = right + 1
            for level in range(levels - 1, -1, -1):
                if p == n:
                    break
                q = dest[level][p]
                if q <= limit and q > p:
                    total += sums[level][p]
                    p = q
            if p < n:
                end = min(right, nxt[p] - 1)
                if end > p:
                    total += nums[p] * (end - p) - (prefix[end + 1] - prefix[p + 1])
            return total

        answer = 0
        for left in range(n):
            lo, hi = left, n
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(left, mid - 1) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - left
        return answer

