class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n=len(edges)+1
        g=[[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        parent=[-1]*n
        parent_w=[0]*n
        order=[0]
        parent[0]=0
        for u in order:
            for v,w in g[u]:
                if v != parent[u]:
                    parent[v]=u
                    parent_w[v]=w
                    order.append(v)
        dp0=[0]*n
        dp1=[0]*n
        for u in reversed(order):
            base=0
            gains=[]
            for v,w in g[u]:
                if parent[v]==u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])
            gains.sort(reverse=True)
            dp0[u]=base + sum(x for x in gains[:k] if x>0)
            dp1[u]=base + sum(x for x in gains[:max(0,k-1)] if x>0)
        return dp0[0]

