import sys
MOD = 998244353

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    ans = []
    for _ in range(t):
        h, w = int(data[pos]), int(data[pos + 1])
        pos += 2
        grid = data[pos:pos + h]
        pos += h

        row_pre = []
        col_pre = [0] * w
        ok = True
        for row in grid:
            pre = 0
            vals = [0] * w
            for j, ch in enumerate(row):
                vals[j] = pre
                if ch == 65:
                    pre ^= 1
            if pre:
                ok = False
            row_pre.append(vals)
        if any((sum(grid[i][j] == 65 for i in range(h)) & 1) for j in range(w)):
            ok = False
        if not ok:
            ans.append('0')
            continue

        n = h + w
        parent = list(range(n))
        size = [1] * n
        parity = [0] * n

        def find(x):
            if parent[x] != x:
                old = parent[x]
                parent[x] = find(old)
                parity[x] ^= parity[old]
            return parent[x]

        consistent = True
        for i, row in enumerate(grid):
            for j, ch in enumerate(row):
                if ch == 66:
                    # row phase xor column phase = complement of the two prefix parities
                    v = 1 ^ row_pre[i][j] ^ col_pre[j]
                    a, b = i, h + j
                    ra, rb = find(a), find(b)
                    xa, xb = parity[a], parity[b]
                    if ra == rb:
                        if (xa ^ xb) != v:
                            consistent = False
                    else:
                        if size[ra] < size[rb]:
                            ra, rb = rb, ra
                            xa, xb = xb, xa
                        parent[rb] = ra
                        parity[rb] = xa ^ xb ^ v
                        size[ra] += size[rb]
            for j, ch in enumerate(row):
                if ch == 65:
                    col_pre[j] ^= 1

        if not consistent:
            ans.append('0')
        else:
            roots = sum(find(x) == x for x in range(n))
            ans.append(str(pow(2, roots, MOD)))
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    solve()

