class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)

        def occurrences(word):
            if not word:
                return list(range(n + 1))
            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j

            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        def build_next(occ):
            nxt = [-1] * (n + 2)
            j = len(occ) - 1
            nearest = -1
            for i in range(n, -1, -1):
                while j >= 0 and occ[j] >= i:
                    nearest = occ[j]
                    j -= 1
                nxt[i] = nearest
            return nxt

        oa = occurrences(a)
        ob = occurrences(b)
        oc = occurrences(c)
        next_b = build_next(ob)
        next_c = build_next(oc)

        starts = oa if a else range(n + 1)
        answer = n + 1
        for start in starts:
            pos = start + len(a)
            if pos > n:
                continue
            b_start = next_b[pos]
            if b_start < 0:
                continue
            pos = b_start + len(b)
            if pos > n:
                continue
            c_start = next_c[pos]
            if c_start >= 0:
                answer = min(answer, c_start + len(c) - start)

        return -1 if answer == n + 1 else answer

