import sys
import itertools

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    total_xor = 0
    for value in a:
        total_xor ^= value

    r = min(k, n - k)
    best = 0
    if k <= n - k:
        for chosen in itertools.combinations(range(n), r):
            value = 0
            for i in chosen:
                value ^= a[i]
            if value > best:
                best = value
    else:
        # The XOR of a subset equals total_xor XOR the XOR of its complement.
        for omitted in itertools.combinations(range(n), r):
            value = total_xor
            for i in omitted:
                value ^= a[i]
            if value > best:
                best = value

    print(best)

if __name__ == '__main__':
    main()

