from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Iterative postorder traversal, preserving increasing child order.
        order = []
        stack = [(0, False)]
        while stack:
            u, done = stack.pop()
            if done:
                order.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        pos = [0] * n
        size = [1] * n
        for i, u in enumerate(order):
            pos[u] = i
            if parent[u] != -1:
                size[parent[u]] += size[u]

        # Prefix XOR of character parity masks in the postorder string.
        pref = [0]
        for u in order:
            pref.append(pref[-1] ^ (1 << (ord(s[u]) - ord('a'))))

        answer = [False] * n
        for u in range(n):
            end = pos[u]
            start = end - size[u] + 1
            parity = pref[end + 1] ^ pref[start]
            answer[u] = parity.bit_count() <= 1
        return answer

