from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix-index residue modulo k, retain the smallest
        # preceding prefix sum. A valid subarray has endpoints with equal residues.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = None

        for i, value in enumerate(nums, 1):
            prefix += value
            residue = i % k
            previous = min_prefix[residue]
            if previous is not None:
                candidate = prefix - previous
                if best is None or candidate > best:
                    best = candidate
            if previous is None or prefix < previous:
                min_prefix[residue] = prefix

        return best

