class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        # dp[i] is the resulting length after the current number of steps,
        # starting from character 'a' + i.
        dp = [1] * 26
        for _ in range(t):
            ndp = [0] * 26
            for i in range(25):
                ndp[i] = dp[i + 1]
            ndp[25] = (dp[0] + dp[1]) % MOD
            dp = ndp
        return sum(dp[ord(ch) - ord('a')] for ch in s) % MOD

