from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = Counter(nums)
        answer = None

        # If x is the outlier and y is the sum of the special numbers,
        # then total = (sum of specials) + y + x = 2*y + x.
        for x in freq:
            remainder = total - x
            if remainder % 2 == 0:
                y = remainder // 2
                # Outlier and sum element must use distinct indices.
                needed = 2 if x == y else 1
                if freq.get(y, 0) >= needed:
                    if answer is None or x > answer:
                        answer = x

        return answer

