class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Bit s in dp[i] indicates that sum s can be formed at index i.
        dp = [1] * n  # Initially, only sum 0 is reachable.

        if all(value == 0 for value in nums):
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << value
                # Sums above nums[i] cannot contribute to a solution.
                dp[i] &= (1 << (nums[i] + 1)) - 1

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

