                for x in range(p * p, 10000, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        digits = len(str(n))
        powers = [10 ** i for i in range(digits)]
        dist = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            for place in powers:
                digit = (value // place) % 10
                if digit > 0:
                    nxt = value - place
                    new_cost = cost + nxt
                    if not prime[nxt] and new_cost < dist.get(nxt, float('inf')):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))
                if digit < 9:
                    nxt = value + place
                    new_cost = cost + nxt
                    if not prime[nxt] and new_cost < dist.get(nxt, float('inf')):
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

