class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z0[k] is the LCP of nums and nums[k:].
        z0 = [0] * n
        left = right = 0
        for k in range(1, n):
            if k <= right:
                z0[k] = min(right - k + 1, z0[k - left])
            while k + z0[k] < n and nums[z0[k]] == nums[k + z0[k]]:
                z0[k] += 1
            if k + z0[k] - 1 > right:
                left, right = k, k + z0[k] - 1

        answer = 0
        # i is the length of nums1; d is the length of nums2.
        for i in range(1, n - 1):
            m = n - i
            z = [0] * m
            left = right = 0
            for d in range(1, m):
                if d <= right:
                    z[d] = min(right - d + 1, z[d - left])
                while d + z[d] < m and nums[i + z[d]] == nums[i + d + z[d]]:
                    z[d] += 1
                if d + z[d] - 1 > right:
                    left, right = d, d + z[d] - 1

            # If nums1 is a prefix of nums2, every d >= i is valid.
            first_prefix = z0[i] >= i
            if first_prefix:
                answer += max(0, m - i)
            # For d < i, only the condition nums2 is a prefix of nums3 can apply.
            for d in range(1, min(i, m)):
                if z[d] >= d:
                    answer += 1
        return answer

