from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        incoming = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            incoming[b].append((a, w))
            weights.append(w)
        values = sorted(set(weights))

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            queue = deque([0])
            reached = 1
            while queue:
                v = queue.popleft()
                for u, weight in incoming[v]:
                    if weight <= limit and not seen[u]:
                        seen[u] = True
                        reached += 1
                        queue.append(u)
            return reached == n

        if not feasible(values[-1]):
            return -1

        low, high = 0, len(values) - 1
        while low < high:
            mid = (low + high) // 2
            if feasible(values[mid]):
                high = mid
            else:
                low = mid + 1
        return values[low]

