from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state records the colors of a symmetric pair, from left to right.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Add pairs from the outside toward the center. Consecutive pairs must
        # differ on both sides, which enforces all adjacent-house constraints.
        for i in range(1, n // 2):
            next_dp = [10**30] * len(states)
            for cur, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for prev, (pa, pb) in enumerate(states):
                    if a != pa and b != pb:
                        next_dp[cur] = min(next_dp[cur], dp[prev] + pair_cost)
            dp = next_dp

        return min(dp)

